args.command:
cd /workspace && mkdir -p /tmp/t && cat > /tmp/t/file1.c <<'EOF'
int main()
{
    char a[10];
    a[10] = 0;
    return 0;
}
EOF
./executable /tmp/t/file1.c; echo "exit=$?"

cd /workspace && run(){ ./executable.orig "$@" >/tmp/o 2>/tmp/e; ec=$?; echo "== $1 | exit=$ec"; head -c 400 /tmp/o; [ -s /tmp/e ] && { echo "--stderr--"; head -c 300 /tmp/e; }; }
p(){ printf '%s\n' "$2" > /tmp/t/db.json; run "db=$2" --project=/tmp/t/db.json; }
p a '[[]]'; p b '["x"]'; p c '[null]'; p d '[{}]'; p e '[{"command":123}]'; p f '[{"arguments":"gcc"}]'; p g '[{"command":"gcc a.c","directory":5,"file":"a.c"}]'; p h '[{"command":"gcc a.c","directory":"/tmp","file":5}]'; p i '[{"command":"","directory":"/tmp","file":"a.c"}]'; p j '[{"arguments":[],"directory":"/tmp","file":"a.c"}]'; p k '[{"command":"gcc a.c","directory":"/tmp","file":"a.c"},{"command":"gcc b.c","directory":"/tmp","file":"b.c"}]'; p l ' [ ] '; p m '[{"command":"gcc a.c","output":"a.o","file":"a.c"}]'
printf '<foo/>\n' > /tmp/t/f.vcxproj; run "vcxproj-foo" --project=/tmp/t/f.vcxproj
printf '' > /tmp/t/empty.vcxproj; run "vcxproj-empty" --project=/tmp/t/empty.vcxproj
printf '<?xml version="1.0"?><Project><ItemGroup><ClCompile Include="a.c"/></ItemGroup></Project>\n' > /tmp/t/real.vcxproj; run "vcxproj-real" --project=/tmp/t/real.vcxproj
